import { test } from "node:test";
import assert from "node:assert/strict";
import * as glance from "../shared/libraryGlance.mjs";

/**
 * DECISION 28 (GO v3, my pick, pending Jeremy; 10/23 read F4): the centers
 * have one name, "centers". The one place the shop said "hubs" was the
 * Reflector's one-liner, the library's own words (HD-Library-Work
 * types.json, regenerated by tools/library-glance.mjs).
 */
test("decision 28: the Reflector's one-liner says centers", () => {
  assert.equal(glance.TYPE_GLANCE.Reflector, "No steady centers of its own. Reflects the people and places around it.");
});

test("decision 28: no 'hub' in any library one-liner the shop prints", () => {
  for (const [name, table] of Object.entries(glance)) {
    if (!table || typeof table !== "object") continue;
    for (const [k, v] of Object.entries(table)) assert.doesNotMatch(String(v), /\bhubs?\b/i, `${name}.${k}`);
  }
});
